use anyhow::{Context, Result, ensure};
use media_inference_lab::{guards::{GuardConfig, GuardMonitor}, maintenance::{self, Transaction}, process_scope::{self, CommandSpec, OwnedProcess, ProcessIdentity, ProcessState}};
use serde_json::{Value, json};
use std::{collections::BTreeMap, fs::{self, OpenOptions}, io::Read, os::unix::fs::{DirBuilderExt, OpenOptionsExt}, path::{Path, PathBuf}, process::{Child, Command, Stdio}, thread, time::{Duration, Instant}};
fn emit(value:Value){println!("{value}");}
fn read_json(path:&Path)->Result<Value>{ensure!(fs::metadata(path)?.len()<=16*1024*1024,"proof JSON bound");Ok(serde_json::from_slice(&fs::read(path)?)?)}
fn fresh(path:&Path)->Result<std::fs::File>{Ok(OpenOptions::new().write(true).create_new(true).mode(0o600).open(path)?)}
fn pause(end:Instant)->Result<()>{ensure!(Instant::now()<end,"owned proof deadline expired");thread::sleep(Duration::from_millis(20));Ok(())}
struct Fixture { actor:OwnedProcess,end:Instant,settled:bool }
impl Fixture {
 fn start(spec:&CommandSpec,end:Instant)->Result<Self>{
  let attempt=OwnedProcess::spawn_with_deadline(spec,Instant::now()+Duration::from_secs(2),&mut ||Ok(()))?;
  let fixture=Self{actor:attempt.process,end,settled:false};
  ensure!(attempt.failure.is_none(),"owned fixture enrollment failed: {:?}",attempt.failure);Ok(fixture)
 }
 fn finish(&mut self)->Result<()>{
  if self.settled{return Ok(());}self.settled=true;
  let result=self.actor.settle(self.end,Duration::from_millis(100),&mut ||Ok(()));
  emit(json!({"owned_fixture_pid":self.actor.pid(),"settlement":result.as_ref().ok(),"settlement_error":result.as_ref().err().map(|e|format!("{e:#}"))}));
  ensure!(result?.complete,"owned fixture settlement incomplete");Ok(())
 }
}
impl Drop for Fixture { fn drop(&mut self){let _=self.finish();} }
struct Controller { child:Child, end:Instant, receipt:Option<PathBuf> }
impl Drop for Controller {
 fn drop(&mut self){
  while matches!(self.child.try_wait(),Ok(None))&&Instant::now()<self.end{thread::sleep(Duration::from_millis(20));}
  if matches!(self.child.try_wait(),Ok(None)){let _=self.child.kill();}
  let _=self.child.wait();
  if let Some(path)=&self.receipt{
   while Instant::now()<self.end{
    if let Ok(value)=read_json(path) && let Some(pid)=value["guardian_pid"].as_u64() && matches!(process_scope::observe(pid as u32),Ok(None)){return;}
    thread::sleep(Duration::from_millis(20));
   }
  }
 }
}
fn collect_identities(value:&Value,out:&mut BTreeMap<u32,ProcessIdentity>){
 if let Ok(identity)=serde_json::from_value::<ProcessIdentity>(value.clone()){out.insert(identity.pid,identity);return;}
 match value{Value::Array(values)=>for value in values{collect_identities(value,out);},Value::Object(values)=>for value in values.values(){collect_identities(value,out);},_=>{}}
}
fn cpu(mil:&Path,root:&Path,scenario:&str)->Result<()>{
 fs::DirBuilder::new().mode(0o700).create(root)?;
 let end=Instant::now()+Duration::from_secs(40);
 let mut foreign=if scenario=="unmanaged-controller-loss"{
  Some(Fixture::start(&CommandSpec{executable:mil.to_owned(),args:vec!["maintenance-participant".into(),"--mode".into(),"service".into(),"--duration-ms".into(),"30000".into()],cwd:root.to_owned(),environment:BTreeMap::new()},end)?)
 }else{None};
 let before=foreign.as_ref().map(|f|f.actor.identity()).transpose()?;
 if let Some(identity)=&before{ensure!(identity.state==ProcessState::Running,"foreign fixture not running");emit(json!({"foreign_before":identity,"guardian_has_no_ownership":true}));}
 let stdout=root.join("controller.stdout");
 let child=Command::new(mil).args(["maintenance-cpu","--root"]).arg(root).args(["--scenario",scenario]).env_clear().stdout(Stdio::from(fresh(&stdout)?)).stderr(Stdio::from(fresh(&root.join("controller.stderr"))?)).spawn()?;
 let mut controller=Controller{child,end,receipt:None};
 let protocol=loop{
  ensure!(fs::metadata(&stdout)?.len()<=65536,"controller protocol bound");
  if let Some(line)=fs::read_to_string(&stdout)?.lines().next() && let Ok(value)=serde_json::from_str::<Value>(line){break value;}
  ensure!(controller.child.try_wait()?.is_none(),"controller exited before protocol");pause(end)?;
 };
 let receipt=PathBuf::from(protocol["receipt"].as_str().context("receipt")?);controller.receipt=Some(receipt.clone());
 emit(json!({"scenario":scenario,"protocol":protocol}));
 let journal=receipt.parent().context("receipt parent")?.join("guardian.jsonl");
 if scenario=="unmanaged-controller-loss"{
  loop{
   let text=fs::read_to_string(&journal).unwrap_or_default();ensure!(text.len()<=64*1024*1024,"journal bound");
   if text.lines().filter_map(|line|serde_json::from_str::<Value>(line).ok()).any(|v|v["phase"]=="experiment_created"){break;}pause(end)?;
  }
  controller.child.kill()?;let status=controller.child.wait()?;
  emit(json!({"controlled_only_owned_controller":controller.child.id(),"reaped":true,"status":status.to_string()}));
 }
 let result=loop{if receipt.exists(){break read_json(&receipt)?;}pause(end)?;};
 let status=loop{if let Some(status)=controller.child.try_wait()?{break status;}pause(end)?;};
 let services=read_json(&receipt.parent().unwrap().join("service-outcomes.json"))?;
 let unmanaged=scenario.starts_with("unmanaged-");
 let expected_success=scenario=="unmanaged-normal";
 ensure!(result["success"]==expected_success,"unexpected lifecycle outcome");
 ensure!(result["service_accounting_complete"]==true,"helper accounting incomplete");
 if unmanaged{
  ensure!(result["creation_attempted"]==true&&result["settlement"]["complete"]==true,"experiment unaccounted");
  ensure!(result["restored"]==true&&services[0]["restored"]==true,"Studio restoration failed");
  let excluded=&services[1];
  ensure!(excluded["unmanaged"]["state"]=="unverified"&&excluded["unmanaged"]["policy"]=="unmanaged","unmanaged evidence missing");
  ensure!(excluded["root"].is_null()&&excluded["gui"].is_null()&&excluded["launch_record"].is_null()&&excluded["absence"].is_null(),"false ownership or absence");
  ensure!(excluded["inhibited"]==false&&excluded["restored"]==false&&excluded["actors"].as_array().context("actors")?.is_empty(),"false oMLX control");
 }else{ensure!(result["creation_attempted"]==false,"strict absence unexpectedly admitted");}
 if scenario!="unmanaged-controller-loss"{ensure!(status.code()==Some(if expected_success{0}else{1}),"CLI status differs from outcome");}
 let journal_text=fs::read_to_string(&journal)?;ensure!(journal_text.len()<=64*1024*1024,"journal bound");
 let entries=journal_text.lines().map(serde_json::from_str::<Value>).collect::<std::result::Result<Vec<_>,_>>()?;
 if unmanaged{ensure!(!entries.iter().any(|v|matches!(v["phase"].as_str(),Some("omlx_stop"|"omlx_restore"|"omlx_absence_admission"|"omlx_absence_prelaunch"))),"false lifecycle journal claim");}
 if let Some(identity)=before{
  let after=process_scope::verify_identity(&identity)?;ensure!(after.state==ProcessState::Running,"foreign fixture changed");
  emit(json!({"foreign_before":identity,"foreign_after":after,"same_birth_and_running":true,"guardian_has_no_ownership":true}));
 }
 if let Some(fixture)=foreign.as_mut(){fixture.finish()?;}
 let guardian=protocol["guardian_pid"].as_u64().context("guardian pid")? as u32;
 while process_scope::observe(guardian)?.is_some(){pause(end)?;}
 let mut identities=BTreeMap::new();collect_identities(&result,&mut identities);collect_identities(&services,&mut identities);for entry in &entries{collect_identities(entry,&mut identities);}
 let mut absent=Vec::new();
 for (pid,identity) in identities{let current=process_scope::observe(pid)?;ensure!(!current.as_ref().is_some_and(|p|p.same_process(&identity)),"owned process remains: {pid}");absent.push(pid);}
 emit(json!({"scenario":scenario,"behavior_pass":true,"receipt":receipt,"result":result,"service_outcomes":services,"controller_reaped":true,"guardian_absent":true,"recorded_owned_identities_absent":absent}));Ok(())
}
fn studio(root:&Path,target:&str,plist:&Path)->Result<()>{
 let start=Instant::now();let observation_end=start+Duration::from_secs(2);
 let mut helper=Fixture::start(&CommandSpec{executable:"/bin/launchctl".into(),args:vec!["list".into()],cwd:root.to_owned(),environment:BTreeMap::new()},start+Duration::from_secs(4))?;
 let mut stdout=Vec::new();let mut stderr_bytes=0usize;let mut total=0usize;
 let capture=(||->Result<()>{loop{
  ensure!(Instant::now()<observation_end,"Studio list observation expired");let exited=helper.actor.exited_unreaped()?;
  for (stream,is_stdout) in [(&mut helper.actor.stdout,true),(&mut helper.actor.stderr,false)]{if let Some(stream)=stream{loop{let mut bytes=[0u8;4096];match stream.read(&mut bytes){
   Ok(0)=>break,Ok(n)=>{total+=n;ensure!(total<=65536,"Studio list output bound");if is_stdout{stdout.extend_from_slice(&bytes[..n]);}else{stderr_bytes+=n;}},
   Err(e) if e.kind()==std::io::ErrorKind::WouldBlock=>break,Err(e)=>return Err(e.into())
  }}}}
  if exited{break;}thread::sleep(Duration::from_millis(2));
 }Ok(())})();
 helper.finish()?;capture?;ensure!(stderr_bytes==0,"Studio list diagnostics omitted");
 let label=target.rsplit('/').next().context("target label")?;
 let text=String::from_utf8(stdout).context("non UTF8 list output omitted")?;
 let rows:Vec<_>=text.lines().filter_map(|line|{let fields:Vec<_>=line.split_whitespace().collect();(fields.len()==3&&fields[2]==label).then(||fields.iter().map(|v|v.to_string()).collect::<Vec<_>>())}).collect();
 ensure!(rows.len()==1,"Studio target row unavailable or ambiguous");let pid=rows[0][0].parse::<u32>().context("Studio PID unavailable")?;
 let identity=process_scope::observe(pid)?.context("Studio identity unavailable")?;
 ensure!(identity.state==ProcessState::Running,"Studio not running");
 ensure!(target.starts_with(&format!("gui/{}/",identity.uid)),"Studio owner mismatch");
 let group=process_scope::group_members(identity.pgid)?;let after=process_scope::verify_identity(&identity)?;
 ensure!(after.state==ProcessState::Running,"Studio identity changed");
 emit(json!({"kind":"studio_permitted_metadata_only","target":target,"selected_list_row":rows[0],"opaque_plist_reference":plist,"identity":identity,"identity_after":after,"group":group,"elapsed_us":start.elapsed().as_micros(),"registration_path_verified":false,"production_print_qualification":"not_permitted_pending_separate_collection_authority","listener_qualification":"not_attempted_not_required_by_current_Studio_enrollment","collection":"list PID/status/label plus targeted identity/group; no print/plist contents/argv/env/API/logs/control"}));Ok(())
}
fn resources(root:&Path)->Result<()>{let start=Instant::now();let monitor=GuardMonitor::start(GuardConfig{min_disk_free_bytes:10*1024*1024*1024,max_disk_growth_bytes:256*1024*1024,sample_interval_ms:100},root)?;emit(json!({"kind":"resource_baseline_only","elapsed_us":start.elapsed().as_micros(),"report":monitor.report(),"no_lease_or_gpu_exclusivity":true}));Ok(())}
fn candidate(path:&Path)->Result<()>{let transaction:Transaction=maintenance::read_private(path)?;transaction.validate()?;emit(json!({"pure_candidate_validation":true,"transaction_sha256":maintenance::digest(&transaction)?,"guardian_sha256":transaction.guardian_sha256,"authorization_created":false,"service_controls":false}));Ok(())}
fn main()->Result<()>{let args:Vec<_>=std::env::args().collect();match args.get(1).map(String::as_str){
 Some("cpu")=>cpu(Path::new(args.get(2).context("mil")?),Path::new(args.get(3).context("root")?),args.get(4).context("scenario")?),
 Some("studio")=>studio(Path::new(args.get(2).context("root")?),args.get(3).context("target")?,Path::new(args.get(4).context("plist")?)),
 Some("resources")=>resources(Path::new(args.get(2).context("root")?)),
 Some("candidate")=>candidate(Path::new(args.get(2).context("transaction")?)),
 _=>anyhow::bail!("explicit proof operation required")}}
